#!/usr/bin/env node
/**
 * The committed ts-rs bindings must be what the Rust types generate.
 *
 * `citadel-workspace-types/bindings/*.ts` is generated by ts-rs, which runs as
 * part of `cargo test -p citadel-workspace-types`. CI regenerates and then
 * asserts the tree is clean:
 *
 *     git diff --exit-code -- citadel-workspace-types/bindings
 *
 * Nothing local did. So a doc comment expanded on `DomainPermissions` — twenty
 * lines explaining why `serde(default)` is there — went in, was never
 * regenerated, and turned that CI job red. It stayed red across 103 commits,
 * because the parent had no open PR and therefore no CI at all; the first run
 * on the branch found it.
 *
 * The failure is not the doc comment. It is that the ONLY thing asserting this
 * was a plain shell step in the workflow, and
 * `check-preflight-runs-what-ci-runs` compares `node scripts/*.mjs`
 * invocations — a `run: git diff` is invisible to it by construction. An
 * assertion a developer cannot run is an assertion they learn about from a red
 * CI job, one full cycle later.
 *
 * This runs the generator and the diff, so preflight says it before the push.
 *
 * `SKIP_WASM_BUILD=1`, as every parent cargo command here needs: `build.rs`
 * otherwise runs wasm-pack and can clobber the committed WASM artefacts.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const BINDINGS = join(ROOT, 'citadel-workspace-types', 'bindings');
const REL = 'citadel-workspace-types/bindings';

if (!existsSync(BINDINGS)) {
  console.error(`FAIL: ${REL} does not exist — the bindings moved and this gate read nothing.`);
  process.exit(1);
}

// Vacuity floor. An empty or near-empty directory diffs clean against itself,
// so "no changes" would be reported over nothing at all.
const committed = readdirSync(BINDINGS).filter((f) => f.endsWith('.ts'));
if (committed.length < 20) {
  console.error(
    `FAIL: only ${committed.length} binding file(s) in ${REL}; there are dozens.\n` +
      'The generator target moved, and a clean diff here would mean nothing.',
  );
  process.exit(1);
}

// The tree must be clean HERE before regenerating, or an unrelated in-progress
// edit to a binding is reported as a stale-generation failure — which sends the
// reader looking for a Rust change that does not exist.
function dirty() {
  return execFileSync('git', ['status', '--porcelain', '--', REL], { cwd: ROOT, encoding: 'utf8' })
    .trim();
}

if (dirty()) {
  console.error(
    `FAIL: ${REL} already has uncommitted changes, so regenerating cannot tell\n` +
      'a stale binding from your own edit:\n\n' +
      `${dirty()}\n\n` +
      'Commit or stash those first. The bindings are generated — an edit here is\n' +
      'almost certainly a change that belongs in the Rust type.',
  );
  process.exit(1);
}

try {
  execFileSync('cargo', ['test', '-p', 'citadel-workspace-types', '--quiet'], {
    cwd: ROOT,
    encoding: 'utf8',
    stdio: 'pipe',
    env: { ...process.env, SKIP_WASM_BUILD: '1' },
    timeout: 900_000,
  });
} catch (error) {
  console.error(
    'FAIL: `cargo test -p citadel-workspace-types` did not complete, so the bindings\n' +
      'were never regenerated and this gate proved nothing.\n\n' +
      `${error.stderr ?? error}`,
  );
  process.exit(1);
}

const changed = dirty();
if (changed) {
  console.error(`::error::${REL} is stale — the Rust types generate something different.`);
  console.error(`\nFAIL: regenerating changed ${changed.split('\n').length} committed binding(s):\n`);
  console.error(changed);
  console.error(
    `\n${execFileSync('git', ['diff', '--', REL], { cwd: ROOT, encoding: 'utf8' }).slice(0, 4000)}`,
  );
  console.error(
    'These files are generated by ts-rs during `cargo test -p citadel-workspace-types`.\n' +
      'The regenerated versions are in your working tree now — commit them.\n' +
      '\nA doc comment on a Rust type is part of the binding, so editing one and not\n' +
      'regenerating is enough to do this.',
  );
  process.exit(1);
}

console.log(
  `check-committed-bindings-match-the-rust: ${committed.length} binding(s) regenerated from the ` +
    'Rust types; none differs from what is committed.',
);
